function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  if (input.confirm_execute !== true) throw new Error('Paper rebalance execution requires an explicit user request and confirm_execute=true')
  const strategyId = String(input.strategy_id || '').trim()
  const signalId = String(input.signal_id || '').trim()
  if (!strategyId && !signalId) throw new Error('Provide strategy_id or signal_id')
  const response = await fetch(apiOrigin() + '/api/paper/rebalance/execute', {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify({ strategy_id: strategyId || null, signal_id: signalId || null, profile: input.profile === 'runtime' ? 'runtime' : 'demo', account_id: String(input.account_id || 'paper'), confirm: true }),
  })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}
